import React from 'react';
import { api } from '../lib/api';
import { useStore } from '@nanostores/react';
import { cartCount, addToCart } from '../cart/cartStore';

function WishlistPage() {
  const [wishlist, setWishlist] = React.useState<any[]>([]);
  const count = useStore(cartCount);

  React.useEffect(() => {
    api.get('/wishlist').then(setWishlist);
  }, []);

  const removeFromWishlist = async (item: any) => {
    await api.delete(`/wishlist/${item.sku}`);
    setWishlist(wishlist.filter(i => i.sku !== item.sku));
  };

  return (
    <div className="wishlist-page">
      <h1>Your Wishlist</h1>
      {wishlist.length === 0 ? (
        <p>Your wishlist is empty.</p>
      ) : (
        <div className="wishlist-grid">
          {wishlist.map(item => (
            <div key={item.sku} className="wishlist-item">
              <img src={item.image} alt={item.name} />

              <button
                className="btn btn-primary"
                onClick={() => addToCart({ ...item, qty: 1 })}
              >
                Add to Cart
              </button>

              <button
                className="btn btn-secondary"
                onClick={() => removeFromWishlist(item)}
              >
                Remove
              </button>

              <div className="product-card__details">
                <span>{item.name}</span>
                <span>{item.price}</span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default WishlistPage;
